def connectivity_timeline(n, operations):
    Q = len(operations)
    if Q == 0:
        return []

    active = {}
    tree = [[] for _ in range(4 * Q)]

    def add_to_tree(node, l, r, ql, qr, edge):
        if ql <= l and r <= qr:
            tree[node].append(edge)
            return
        mid = (l + r) >> 1
        if ql <= mid:
            add_to_tree(node << 1, l, mid, ql, qr, edge)
        if qr > mid:
            add_to_tree(node << 1 | 1, mid + 1, r, ql, qr, edge)

    for i, op in enumerate(operations):
        if op[0] == 'add':
            u, v = op[1], op[2]
            if u > v: u, v = v, u
            active[(u, v)] = i
        elif op[0] == 'remove':
            u, v = op[1], op[2]
            if u > v: u, v = v, u
            t = active.pop((u, v))
            add_to_tree(1, 0, Q - 1, t, i - 1, (u, v))
    for (u, v), t in active.items():
        add_to_tree(1, 0, Q - 1, t, Q - 1, (u, v))

    parent = list(range(n))
    size = [1] * n
    history = []

    def find(i):
        while parent[i] != i:
            i = parent[i]
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            if size[root_i] < size[root_j]:
                root_i, root_j = root_j, root_i
            parent[root_j] = root_i
            size[root_i] += size[root_j]
            history.append((root_j, root_i))
            return True
        return False

    def rollback(k):
        while len(history) > k:
            v, u = history.pop()
            size[u] -= size[v]
            parent[v] = v

    res = []

    def dfs(node, l, r):
        k = len(history)
        for u, v in tree[node]:
            union(u, v)
        if l == r:
            op = operations[l]
            if op[0] == 'ask':
                res.append(find(op[1]) == find(op[2]))
        else:
            mid = (l + r) >> 1
            dfs(node << 1, l, mid)
            dfs(node << 1 | 1, mid + 1, r)
        rollback(k)

    dfs(1, 0, Q - 1)
    return res
