def minPath(grid, k):
    if k == 0:
        return []
    n = len(grid)
    start_r = start_c = -1
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                start_r, start_c = r, c
                break
        if start_r != -1:
            break

    path = [1]
    curr_r, curr_c = start_r, start_c
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    for _ in range(k - 1):
        best_r, best_c = curr_r, curr_c
        best_val = float('inf')
        for dr, dc in directions:
            nr, nc = curr_r + dr, curr_c + dc
            if 0 <= nr < n and 0 <= nc < n:
                val = grid[nr][nc]
                if val < best_val:
                    best_val = val
                    best_r, best_c = nr, nc
        if best_val == float('inf'):
            best_val = grid[curr_r][curr_c]
        path.append(best_val)
        curr_r, curr_c = best_r, best_c

    return path
