def regex_match(pattern, text):
    tokens = []
    i = 0
    n_pat = len(pattern)
    while i < n_pat:
        if pattern[i] == '[':
            j = i + 1
            while j < n_pat and pattern[j] != ']':
                j += 1
            content = pattern[i+1:j]
            negated = content.startswith('^')
            if negated:
                content = content[1:]
            char_set = set(content)
            def make_match(cs, neg):
                def match(c):
                    return (c in cs) != neg
                return match
            tokens.append((make_match(char_set, negated), None))
            i = j + 1
        elif pattern[i] == '.':
            tokens.append((lambda c: True, None))
            i += 1
        elif pattern[i] == '\\':
            tokens.append((lambda c, ch=pattern[i+1]: c == ch, None))
            i += 2
        else:
            tokens.append((lambda c, ch=pattern[i]: c == ch, None))
            i += 1

        if i < n_pat and pattern[i] in '*+?':
            quant = pattern[i]
            tokens[-1] = (tokens[-1][0], quant)
            i += 1

    m = len(tokens)
    n = len(text)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[m][n] = True

    for i in range(m - 1, -1, -1):
        match_func, quant = tokens[i]
        for j in range(n, -1, -1):
            if j < n:
                if quant is None:
                    dp[i][j] = match_func(text[j]) and dp[i+1][j+1]
                elif quant == '*':
                    dp[i][j] = dp[i+1][j] or (match_func(text[j]) and dp[i][j+1])
                elif quant == '+':
                    dp[i][j] = match_func(text[j]) and dp[i][j+1]
                elif quant == '?':
                    dp[i][j] = dp[i+1][j] or (match_func(text[j]) and dp[i+1][j+1])
            else:
                if quant in ('*', '?'):
                    dp[i][j] = dp[i+1][j]

    return dp[0][0]
